-- ==========================================================
-- install_all.sql : build both MyTickets databases from nothing.
-- GENERATED by build_install.py from the single files. Do not edit by hand.
--
-- Run it as the owner account (avnadmin on Aiven), as one script.
-- Afterwards: 1) edit the two CHANGE_ME passwords in
--                myv_myTickets_admin/grant/00_accounts_and_grants.sql and run it,
--             2) optional: run sample_data/01_venues_and_seats.sql and 02_events.sql.
--
-- Safe to run again: tables use IF NOT EXISTS, everything else is dropped and recreated.
-- BUT dropping a procedure or function also drops its grants, so after running this
-- on a database that is already in use, run 00_accounts_and_grants.sql again.
-- ==========================================================
SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS myv_myTickets CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE IF NOT EXISTS myv_myTickets_admin CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- ==========================================================
-- myv_myTickets_admin/table/01_admin.sql
-- ==========================================================
USE myv_myTickets_admin;

USE myv_myTickets_admin;

-- Admin accounts. They live in the admin database, separate from customers,
-- so each admin has their own username and password here.
CREATE TABLE IF NOT EXISTS admin (
  admin_id   VARCHAR(20)  NOT NULL,                              -- AD0001, AD0002, ... (generated by a trigger later)
  username   VARCHAR(50)  NOT NULL,
  password   VARCHAR(255) NOT NULL,                              -- store a hash, never the plain text
  `level`    ENUM('staff', 'super_admin') NOT NULL DEFAULT 'staff',
  PRIMARY KEY (admin_id),
  UNIQUE KEY uq_admin_username (username)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==========================================================
-- myv_myTickets_admin/table/02_audit_log.sql
-- ==========================================================
USE myv_myTickets_admin;

USE myv_myTickets_admin;

-- History of what admins did (for example: ADD_EVENT on EV07).
-- Rows are only added by admin procedures, never edited by hand.
CREATE TABLE IF NOT EXISTS audit_log (
  log_id    INT         NOT NULL AUTO_INCREMENT,
  admin_id  VARCHAR(20) NOT NULL,
  action    VARCHAR(30) NOT NULL,                                -- e.g. ADD_EVENT
  target_id VARCHAR(20) NULL,                                    -- id of the thing the action touched, e.g. EV07
  done_at   DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (log_id),
  KEY idx_audit_admin (admin_id),
  CONSTRAINT fk_audit_admin FOREIGN KEY (admin_id) REFERENCES admin (admin_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==========================================================
-- myv_myTickets/table/01_venue.sql
-- ==========================================================
USE myv_myTickets;

CREATE TABLE IF NOT EXISTS venue (
  venue_id VARCHAR(20)  NOT NULL,
  address  VARCHAR(255) NOT NULL,
  capacity INT          NOT NULL,
  PRIMARY KEY (venue_id),
  CONSTRAINT chk_venue_capacity CHECK (capacity > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==========================================================
-- myv_myTickets/table/02_seat.sql
-- ==========================================================
USE myv_myTickets;

CREATE TABLE IF NOT EXISTS seat (
  seat_id     VARCHAR(20) NOT NULL,
  venue_id    VARCHAR(20) NOT NULL,
  seat_zone   VARCHAR(20) NOT NULL,
  seat_row    VARCHAR(10) NULL,
  seat_number INT         NULL,
  PRIMARY KEY (seat_id),
  -- A seat position must be unique inside one venue.
  -- Virtual STANDING seats have NULL row/number, so this UNIQUE key does not block them.
  UNIQUE KEY uq_seat_position (venue_id, seat_zone, seat_row, seat_number),
  CONSTRAINT fk_seat_venue FOREIGN KEY (venue_id) REFERENCES venue (venue_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==========================================================
-- myv_myTickets/table/03_event.sql
-- ==========================================================
USE myv_myTickets;

CREATE TABLE IF NOT EXISTS event (
  event_id          VARCHAR(20)  NOT NULL,
  venue_id          VARCHAR(20)  NOT NULL,
  event_name        VARCHAR(150) NOT NULL,
  artist            VARCHAR(150) NULL,
  sale_time         DATETIME     NOT NULL,
  start_time        DATETIME     NOT NULL,
  standing_capacity INT          NOT NULL DEFAULT 0,
  PRIMARY KEY (event_id),
  CONSTRAINT fk_event_venue FOREIGN KEY (venue_id) REFERENCES venue (venue_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==========================================================
-- myv_myTickets/table/04_membership_tier.sql
-- ==========================================================
USE myv_myTickets;

-- membership_tier: loyalty ranks. A customer's rank is NOT stored; it is computed from how much
-- they have paid (see vw_customer_membership), so it can never get out of date.
--   min_spent         total of paid tickets needed to reach this rank (VND)
--   discount_percent  % taken off the list price when booking
-- There must always be one rank with min_spent = 0, otherwise new customers would have no rank.
CREATE TABLE IF NOT EXISTS membership_tier (
  tier_name        VARCHAR(20)   NOT NULL,
  min_spent        DECIMAL(12,2) NOT NULL,
  discount_percent TINYINT       NOT NULL DEFAULT 0,
  PRIMARY KEY (tier_name),
  CONSTRAINT uq_tier_min_spent UNIQUE (min_spent),
  CONSTRAINT chk_tier_min_spent CHECK (min_spent >= 0),
  CONSTRAINT chk_tier_discount  CHECK (discount_percent BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Starting ranks (INSERT IGNORE: running this script again never duplicates or overwrites them)
INSERT IGNORE INTO membership_tier (tier_name, min_spent, discount_percent) VALUES
  ('Bronze',        0,  0),
  ('Silver',  3000000,  5),
  ('Gold',   10000000, 10),
  ('Platinum', 25000000, 15);

-- ==========================================================
-- myv_myTickets/table/05_customer.sql
-- ==========================================================
USE myv_myTickets;

-- Customers. A customer logs in with their own username and password.
-- Admins are NOT stored here: they live in the separate admin database.
CREATE TABLE IF NOT EXISTS customer (
  customer_id VARCHAR(20)  NOT NULL,                             -- CU0001, CU0002, ... (generated by trg_customer_bi)
  username    VARCHAR(50)  NOT NULL,
  password    VARCHAR(255) NOT NULL,                             -- store a hash, never the plain text
  name        VARCHAR(100) NOT NULL,
  email       VARCHAR(100) NOT NULL,
  phone_num   VARCHAR(20)  NULL,
  PRIMARY KEY (customer_id),
  UNIQUE KEY uq_customer_username (username),
  UNIQUE KEY uq_customer_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==========================================================
-- myv_myTickets/table/06_orders.sql
-- ==========================================================
USE myv_myTickets;

-- customer --place--> orders (1-N). place_at is the attribute of `place`.
CREATE TABLE IF NOT EXISTS orders (
  order_id    VARCHAR(20) NOT NULL,
  customer_id VARCHAR(20) NOT NULL,
  place_at    DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  status      ENUM('pending', 'paid', 'failed') NOT NULL DEFAULT 'pending',
  PRIMARY KEY (order_id),
  CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES customer (customer_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==========================================================
-- myv_myTickets/table/07_ticket.sql
-- ==========================================================
USE myv_myTickets;

-- ticket: key = (seat_id, event_id).
-- order_id    comes from `contain` (orders 1-N ticket)
-- customer_id comes from `buy`     (customer 1-N ticket); trg_ticket_bi keeps it equal to the order's customer
-- pay_method, pay_date are the attributes of `buy`; they stay NULL until pc_pay_order pays the order
CREATE TABLE IF NOT EXISTS ticket (
  seat_id      VARCHAR(20)   NOT NULL,
  event_id     VARCHAR(20)   NOT NULL,
  order_id     VARCHAR(20)   NOT NULL,
  customer_id  VARCHAR(20)   NOT NULL,
  ticket_price DECIMAL(12,2) NOT NULL,
  is_standing  TINYINT(1)    NOT NULL DEFAULT 0,
  pay_method   VARCHAR(30)   NULL,
  pay_date     DATETIME      NULL,
  PRIMARY KEY (seat_id, event_id),
  CONSTRAINT fk_ticket_seat     FOREIGN KEY (seat_id)     REFERENCES seat (seat_id),
  CONSTRAINT fk_ticket_event    FOREIGN KEY (event_id)    REFERENCES event (event_id),
  CONSTRAINT fk_ticket_orders   FOREIGN KEY (order_id)    REFERENCES orders (order_id),
  CONSTRAINT fk_ticket_customer FOREIGN KEY (customer_id) REFERENCES customer (customer_id),
  CONSTRAINT chk_ticket_price   CHECK (ticket_price >= 0),
  CONSTRAINT chk_ticket_pay     CHECK ((pay_method IS NULL AND pay_date IS NULL)
                                    OR (pay_method IS NOT NULL AND pay_date IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==========================================================
-- myv_myTickets/function/fn_available_seats.sql
-- ==========================================================
USE myv_myTickets;

DROP FUNCTION IF EXISTS fn_available_seats;

DELIMITER $$

-- Count the real seats of an event's venue that have no ticket yet (paid or pending) for this event.
-- Virtual STANDING seats are not counted.
-- p_seat_zone = NULL counts every zone; otherwise only the given zone.
-- Returns NULL when the event does not exist.
--
-- Usage:
--   SELECT fn_available_seats('EV01', NULL);
--   SELECT fn_available_seats('EV01', 'VIP');
--   SELECT event_id, event_name, fn_available_seats(event_id, NULL) AS seats_left FROM event;
CREATE FUNCTION fn_available_seats(
  p_event_id  VARCHAR(20),
  p_seat_zone VARCHAR(20)
)
RETURNS INT
READS SQL DATA
BEGIN
  DECLARE v_venue_id VARCHAR(20);
  DECLARE v_cnt      INT;

  SELECT venue_id INTO v_venue_id FROM event WHERE event_id = p_event_id;
  IF v_venue_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COUNT(*) INTO v_cnt
    FROM seat s
   WHERE s.venue_id  = v_venue_id
     AND s.seat_zone <> 'STANDING'
     AND (p_seat_zone IS NULL OR s.seat_zone = p_seat_zone)
     AND NOT EXISTS (SELECT 1 FROM ticket t
                      WHERE t.seat_id  = s.seat_id
                        AND t.event_id = p_event_id);

  RETURN v_cnt;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/function/fn_order_hold_minutes.sql
-- ==========================================================
USE myv_myTickets;

DROP FUNCTION IF EXISTS fn_order_hold_minutes;

DELIMITER $$

-- How many minutes a customer has to pay a pending order before it expires.
-- The single place where this number is defined in the database.
-- (The web app shows the same number on the orders page: ORDER_HOLD_MINUTES in app.py.)
CREATE FUNCTION fn_order_hold_minutes()
RETURNS INT
DETERMINISTIC
BEGIN
  RETURN 15;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/function/fn_standing_left.sql
-- ==========================================================
USE myv_myTickets;

DROP FUNCTION IF EXISTS fn_standing_left;

DELIMITER $$

-- How many STANDING tickets of an event can still be sold:
-- standing_capacity minus the standing tickets that already exist (paid or pending).
-- The counterpart of fn_available_seats, which only counts numbered seats.
-- Returns 0 when the event has no standing area, NULL when the event does not exist.
--
-- Usage:
--   SELECT fn_standing_left('EV01');
--   SELECT event_id, event_name, fn_standing_left(event_id) AS standing_left FROM event;
CREATE FUNCTION fn_standing_left(
  p_event_id VARCHAR(20)
)
RETURNS INT
READS SQL DATA
BEGIN
  DECLARE v_capacity INT;
  DECLARE v_used     INT;

  SELECT standing_capacity INTO v_capacity FROM event WHERE event_id = p_event_id;
  IF v_capacity IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COUNT(*) INTO v_used
    FROM ticket t
    JOIN seat s ON s.seat_id = t.seat_id
   WHERE t.event_id  = p_event_id
     AND s.seat_zone = 'STANDING';

  RETURN GREATEST(v_capacity - v_used, 0);
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/view/vw_customer_membership.sql
-- ==========================================================
USE myv_myTickets;

-- Membership of every customer: total paid, current rank and discount, and the next rank (if any).
--   spent          sum of ticket_price over tickets of PAID orders (cancelled and pending orders do not count)
--   next_tier      NULL when the customer is already at the top rank
--   next_min_spent total needed for the next rank
-- Used by pc_book_tickets (discount) and by the web app (badge and progress).
--
-- Usage:
--   SELECT * FROM vw_customer_membership WHERE customer_id = 'CU0001';
CREATE OR REPLACE VIEW vw_customer_membership AS
SELECT
  s.customer_id,
  s.spent,
  t.tier_name,
  t.discount_percent,
  n.tier_name AS next_tier,
  n.min_spent AS next_min_spent
FROM (
  SELECT c.customer_id,
         COALESCE((SELECT SUM(tk.ticket_price)
                     FROM ticket tk
                     JOIN orders o ON o.order_id = tk.order_id
                    WHERE tk.customer_id = c.customer_id
                      AND o.status = 'paid'), 0) AS spent
    FROM customer c
) s
JOIN      membership_tier t ON t.min_spent = (SELECT MAX(m.min_spent) FROM membership_tier m WHERE m.min_spent <= s.spent)
LEFT JOIN membership_tier n ON n.min_spent = (SELECT MIN(m.min_spent) FROM membership_tier m WHERE m.min_spent >  s.spent);

-- ==========================================================
-- myv_myTickets/view/vw_order_history.sql
-- ==========================================================
USE myv_myTickets;

-- Order history: one row per ticket, together with its order, customer, event, venue and seat.
-- LEFT JOINs keep orders that currently have no tickets (for example failed or cancelled orders,
-- whose tickets were released by trg_orders_au), so they still show up in the history.
--
-- Usage:
--   SELECT * FROM vw_order_history WHERE customer_id = 'CU0001';
--   SELECT * FROM vw_order_history WHERE order_status = 'paid';
CREATE OR REPLACE VIEW vw_order_history AS
SELECT
  o.order_id,
  o.place_at,
  o.status      AS order_status,
  o.customer_id,
  c.username,
  c.name        AS customer_name,
  t.event_id,
  e.event_name,
  e.artist,
  e.start_time,
  v.venue_id,
  v.address     AS venue_address,
  t.seat_id,
  s.seat_zone,
  s.seat_row,
  s.seat_number,
  t.ticket_price,
  t.is_standing,
  t.pay_method,
  t.pay_date
FROM orders o
JOIN      customer c ON c.customer_id = o.customer_id
LEFT JOIN ticket   t ON t.order_id    = o.order_id
LEFT JOIN event    e ON e.event_id    = t.event_id
LEFT JOIN venue    v ON v.venue_id    = e.venue_id
LEFT JOIN seat     s ON s.seat_id     = t.seat_id;

-- ==========================================================
-- myv_myTickets/trigger/trg_customer_bi.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_customer_bi;

DELIMITER $$

-- 1) One person cannot be both a customer and an admin. Admins live in another database
--    (myv_myTickets_admin), so we look into its admin table with the database.table syntax.
-- 2) Generate customer_id = 'CU' + running number (CU0001, CU0002, ...) when none is given.
CREATE TRIGGER trg_customer_bi
BEFORE INSERT ON customer
FOR EACH ROW
BEGIN
  DECLARE v_next INT;

  IF EXISTS (SELECT 1 FROM myv_myTickets_admin.admin WHERE username = NEW.username) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This username is already an admin and cannot also be a customer';
  END IF;

  IF NEW.customer_id IS NULL OR NEW.customer_id = '' THEN
    SELECT COALESCE(MAX(CAST(SUBSTRING(customer_id, 3) AS UNSIGNED)), 0) + 1
      INTO v_next
      FROM customer
     WHERE customer_id REGEXP '^CU[0-9]+$';

    SET NEW.customer_id = CONCAT('CU', LPAD(v_next, GREATEST(4, CHAR_LENGTH(v_next)), '0'));
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_event_bd.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_event_bd;

DELIMITER $$

-- Guard for deleting an event, whatever way the DELETE comes in:
--   * an event that still has tickets (pending or paid) cannot be deleted
--     (cancelling an order removes its tickets, so cancelled orders do not count)
--   * an event that has already started cannot be deleted (it is history)
CREATE TRIGGER trg_event_bd
BEFORE DELETE ON event
FOR EACH ROW
BEGIN
  IF EXISTS (SELECT 1 FROM ticket WHERE event_id = OLD.event_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event has tickets and cannot be deleted';
  END IF;
  IF OLD.start_time <= NOW() THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event has already started and cannot be deleted';
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_event_bi_chk.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_event_bi_chk;

DELIMITER $$

-- Validate a new event: sales must open before the event starts, standing capacity cannot be negative
CREATE TRIGGER trg_event_bi_chk
BEFORE INSERT ON event
FOR EACH ROW
BEGIN
  IF NEW.sale_time >= NEW.start_time THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'sale_time must be earlier than start_time';
  END IF;
  IF NEW.standing_capacity < 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'standing_capacity cannot be negative';
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_event_bi_id.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_event_bi_id;

DELIMITER $$

-- Generate event_id = 'EV' + running number (EV01, EV02, ... EV100) when none is given
CREATE TRIGGER trg_event_bi_id
BEFORE INSERT ON event
FOR EACH ROW
BEGIN
  DECLARE v_next INT;

  IF NEW.event_id IS NULL OR NEW.event_id = '' THEN
    SELECT COALESCE(MAX(CAST(SUBSTRING(event_id, 3) AS UNSIGNED)), 0) + 1
      INTO v_next
      FROM event
     WHERE event_id REGEXP '^EV[0-9]+$';

    SET NEW.event_id = CONCAT('EV', LPAD(v_next, GREATEST(2, CHAR_LENGTH(v_next)), '0'));
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_event_bu_chk.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_event_bu_chk;

DELIMITER $$

-- Same validation as trg_event_bi_chk, applied on update
CREATE TRIGGER trg_event_bu_chk
BEFORE UPDATE ON event
FOR EACH ROW
BEGIN
  IF NEW.sale_time >= NEW.start_time THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'sale_time must be earlier than start_time';
  END IF;
  IF NEW.standing_capacity < 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'standing_capacity cannot be negative';
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_orders_au.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_orders_au;

DELIMITER $$

-- When an order fails, release its seats: delete its tickets, then orphaned virtual STANDING seats
CREATE TRIGGER trg_orders_au
AFTER UPDATE ON orders
FOR EACH ROW
BEGIN
  IF OLD.status = 'pending' AND NEW.status = 'failed' THEN
    -- Tickets first: ticket has a foreign key to seat
    DELETE FROM ticket WHERE order_id = NEW.order_id;

    DELETE FROM seat
     WHERE seat_zone = 'STANDING'
       AND NOT EXISTS (SELECT 1 FROM ticket t WHERE t.seat_id = seat.seat_id);
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_orders_bd.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_orders_bd;

DELIMITER $$

-- A paid order cannot be deleted
CREATE TRIGGER trg_orders_bd
BEFORE DELETE ON orders
FOR EACH ROW
BEGIN
  IF OLD.status = 'paid' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order is already paid and cannot be deleted';
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_orders_bi.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_orders_bi;

DELIMITER $$

-- Generate order_id = 'OD' + running number (OD0001, OD0002, ...) when none is given
CREATE TRIGGER trg_orders_bi
BEFORE INSERT ON orders
FOR EACH ROW
BEGIN
  DECLARE v_next INT;

  IF NEW.order_id IS NULL OR NEW.order_id = '' THEN
    SELECT COALESCE(MAX(CAST(SUBSTRING(order_id, 3) AS UNSIGNED)), 0) + 1
      INTO v_next
      FROM orders
     WHERE order_id REGEXP '^OD[0-9]+$';

    SET NEW.order_id = CONCAT('OD', LPAD(v_next, GREATEST(4, CHAR_LENGTH(v_next)), '0'));
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_orders_bu.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_orders_bu;

DELIMITER $$

-- paid and failed are final states; the customer of an order never changes
-- (tickets copy the customer from the order, so the two must stay equal)
CREATE TRIGGER trg_orders_bu
BEFORE UPDATE ON orders
FOR EACH ROW
BEGIN
  IF OLD.status IN ('paid', 'failed') AND NEW.status <> OLD.status THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order is in a final state and its status cannot be modified';
  END IF;
  IF NEW.customer_id <> OLD.customer_id THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The customer of an order cannot be changed';
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_seat_bi.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_seat_bi;

DELIMITER $$

-- Generate seat_id = 'SE' + running number (SE0001, SE0002, ...) for real seats.
-- Skipped when seat_id is already given, e.g. the virtual STND-... seats inserted by trg_ticket_bi.
CREATE TRIGGER trg_seat_bi
BEFORE INSERT ON seat
FOR EACH ROW
BEGIN
  DECLARE v_next INT;

  IF NEW.seat_id IS NULL OR NEW.seat_id = '' THEN
    SELECT COALESCE(MAX(CAST(SUBSTRING(seat_id, 3) AS UNSIGNED)), 0) + 1
      INTO v_next
      FROM seat
     WHERE seat_id REGEXP '^SE[0-9]+$';

    SET NEW.seat_id = CONCAT('SE', LPAD(v_next, GREATEST(4, CHAR_LENGTH(v_next)), '0'));
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_ticket_bd.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_ticket_bd;

DELIMITER $$

-- Tickets of a paid order cannot be deleted
CREATE TRIGGER trg_ticket_bd
BEFORE DELETE ON ticket
FOR EACH ROW
BEGIN
  IF (SELECT status FROM orders WHERE order_id = OLD.order_id) = 'paid' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ticket is already paid and cannot be cancelled';
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_ticket_bi.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_ticket_bi;

DELIMITER $$

CREATE TRIGGER trg_ticket_bi
BEFORE INSERT ON ticket
FOR EACH ROW
BEGIN
  DECLARE v_venue_event VARCHAR(20);
  DECLARE v_sale        DATETIME;
  DECLARE v_start       DATETIME;
  DECLARE v_stand_cap   INT;
  DECLARE v_zone        VARCHAR(20);
  DECLARE v_seat_venue  VARCHAR(20);
  DECLARE v_customer    VARCHAR(20);
  DECLARE v_status      VARCHAR(10);
  DECLARE v_cnt         INT;
  DECLARE v_next        INT;

  -- Load event info
  SELECT venue_id, sale_time, start_time, standing_capacity
    INTO v_venue_event, v_sale, v_start, v_stand_cap
    FROM event WHERE event_id = NEW.event_id;

  -- Check: tickets can only be sold between sale_time and start_time
  IF NOW() < v_sale OR NOW() >= v_start THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ticket sales are not open for this event';
  END IF;

  -- Check: tickets can only be added to a pending order (paid orders are locked)
  SELECT customer_id, status INTO v_customer, v_status
    FROM orders WHERE order_id = NEW.order_id;
  IF v_status <> 'pending' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Tickets can only be added to a pending order';
  END IF;

  -- buy: the customer of the ticket is the customer who placed the order
  IF NEW.customer_id IS NULL THEN
    SET NEW.customer_id = v_customer;
  ELSEIF NEW.customer_id <> v_customer THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ticket customer must be the customer of the order';
  END IF;

  -- Payment details are filled in only by pc_pay_order, when the order is paid
  IF NEW.pay_method IS NOT NULL OR NEW.pay_date IS NOT NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Payment details are set when the order is paid';
  END IF;

  -- Resolve zone: NULL seat_id means a standing ticket
  IF NEW.seat_id IS NULL THEN
    SET v_zone = 'STANDING';
  ELSE
    SELECT seat_zone, venue_id INTO v_zone, v_seat_venue
      FROM seat WHERE seat_id = NEW.seat_id;
    -- Check: the seat must belong to the venue hosting the event
    IF v_seat_venue <> v_venue_event THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Seat is not in the right venue!';
    END IF;
  END IF;

  -- Check: max 2 tickets per event per customer, across all zones (pending + paid orders)
  SELECT COUNT(*) INTO v_cnt
    FROM ticket t
    JOIN orders o ON o.order_id = t.order_id
   WHERE o.customer_id = v_customer
     AND t.event_id    = NEW.event_id
     AND o.status IN ('pending', 'paid');
  IF v_cnt >= 2 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Maximum 2 tickets per event for one customer';
  END IF;

  -- Check: one order can only contain one seat_zone
  SELECT COUNT(*) INTO v_cnt
    FROM ticket t
    JOIN seat s ON s.seat_id = t.seat_id
   WHERE t.order_id = NEW.order_id
     AND s.seat_zone <> v_zone;
  IF v_cnt > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'One order can only contain one ticket type';
  END IF;

  -- Standing ticket: check capacity, generate id, insert virtual seat (done last)
  IF NEW.seat_id IS NULL THEN
    IF COALESCE(v_stand_cap, 0) <= 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This event has no standing area';
    END IF;

    SELECT COUNT(*) INTO v_cnt
      FROM ticket t
      JOIN seat s ON s.seat_id = t.seat_id
     WHERE t.event_id = NEW.event_id AND s.seat_zone = 'STANDING';
    IF v_cnt >= v_stand_cap THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Out of capacity!';
    END IF;

    -- Order number = current max + 1 (not COUNT, because rows may be deleted)
    SELECT COALESCE(MAX(CAST(SUBSTRING_INDEX(seat_id, '-', -1) AS UNSIGNED)), 0) + 1
      INTO v_next
      FROM seat
     WHERE seat_id LIKE CONCAT('STND-', NEW.event_id, '-%');

    SET NEW.seat_id = CONCAT('STND-', NEW.event_id, '-', LPAD(v_next, 4, '0'));

    INSERT INTO seat (seat_id, venue_id, seat_zone, seat_row, seat_number)
    VALUES (NEW.seat_id, v_venue_event, 'STANDING', NULL, NULL);
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_ticket_bu.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_ticket_bu;

DELIMITER $$

-- Tickets of a paid order are locked.
-- seat_id and event_id are the key; order_id and customer_id must keep matching the order, so none of them can change.
CREATE TRIGGER trg_ticket_bu
BEFORE UPDATE ON ticket
FOR EACH ROW
BEGIN
  IF (SELECT status FROM orders WHERE order_id = OLD.order_id) = 'paid' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ticket is already paid and cannot be modified';
  END IF;
  IF NEW.seat_id <> OLD.seat_id OR NEW.event_id <> OLD.event_id THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The seat or event of a ticket cannot be changed';
  END IF;
  IF NEW.order_id <> OLD.order_id OR NEW.customer_id <> OLD.customer_id THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The order or customer of a ticket cannot be changed';
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/trigger/trg_venue_bi.sql
-- ==========================================================
USE myv_myTickets;

DROP TRIGGER IF EXISTS trg_venue_bi;

DELIMITER $$

-- Generate venue_id = 'VE' + running number (VE01, VE02, ... VE100) when none is given
CREATE TRIGGER trg_venue_bi
BEFORE INSERT ON venue
FOR EACH ROW
BEGIN
  DECLARE v_next INT;

  IF NEW.venue_id IS NULL OR NEW.venue_id = '' THEN
    SELECT COALESCE(MAX(CAST(SUBSTRING(venue_id, 3) AS UNSIGNED)), 0) + 1
      INTO v_next
      FROM venue
     WHERE venue_id REGEXP '^VE[0-9]+$';

    -- LPAD truncates when the number is longer than the width, so the width never drops below the length
    SET NEW.venue_id = CONCAT('VE', LPAD(v_next, GREATEST(2, CHAR_LENGTH(v_next)), '0'));
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/procedure/pc_available_seats.sql
-- ==========================================================
USE myv_myTickets;

DROP PROCEDURE IF EXISTS pc_available_seats;

DELIMITER $$

-- List the real seats of an event's venue that have no ticket yet for this event.
-- Virtual STANDING seats are not listed.
-- p_seat_zone = NULL lists every zone; otherwise only the given zone.
-- Read-only: changes nothing.
CREATE PROCEDURE pc_available_seats(
  IN p_event_id  VARCHAR(20),
  IN p_seat_zone VARCHAR(20)
)
BEGIN
  IF NOT EXISTS (SELECT 1 FROM event WHERE event_id = p_event_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event not found';
  END IF;

  SELECT s.seat_id, s.seat_zone, s.seat_row, s.seat_number
    FROM seat s
    JOIN event e ON e.venue_id = s.venue_id
   WHERE e.event_id  = p_event_id
     AND s.seat_zone <> 'STANDING'
     AND (p_seat_zone IS NULL OR s.seat_zone = p_seat_zone)
     AND NOT EXISTS (SELECT 1 FROM ticket t
                      WHERE t.seat_id  = s.seat_id
                        AND t.event_id = e.event_id)
   ORDER BY s.seat_zone, s.seat_row, s.seat_number;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/procedure/pc_book_tickets.sql
-- ==========================================================
USE myv_myTickets;

DROP PROCEDURE IF EXISTS pc_book_tickets;

DELIMITER $$

-- Book 1 or 2 tickets of ONE seat zone for a customer. Creates a pending order and adds the tickets to it.
-- Real zones: the procedure picks the first free seats (ordered by row, then number).
-- STANDING zone: seat_id is passed as NULL and trg_ticket_bi creates the virtual seat.
-- p_ticket_price is the LIST price of one ticket. The customer's membership discount
-- (vw_customer_membership) is taken off here, and the discounted price is what is stored in the ticket.
-- Everything runs in one transaction: if any ticket fails, the order and all tickets are rolled back.
CREATE PROCEDURE pc_book_tickets(
  IN  p_customer_id  VARCHAR(20),
  IN  p_event_id     VARCHAR(20),
  IN  p_seat_zone    VARCHAR(20),
  IN  p_quantity     INT,
  IN  p_ticket_price DECIMAL(12,2),
  OUT p_order_id     VARCHAR(20)
)
BEGIN
  DECLARE v_venue_id    VARCHAR(20);
  DECLARE v_seat_id     VARCHAR(20);
  DECLARE v_is_standing TINYINT(1);
  DECLARE v_i           INT DEFAULT 0;
  DECLARE v_discount    INT DEFAULT 0;
  DECLARE v_price       DECIMAL(12,2);
  DECLARE v_expired     INT;

  -- On any error: undo everything, then re-raise the original error to the caller
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET p_order_id = NULL;

  -- Release the seats of unpaid orders that timed out (also done every minute by ev_expire_orders)
  CALL pc_expire_orders(v_expired);

  -- Validate input
  IF p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 2 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Quantity must be 1 or 2';
  END IF;
  IF p_seat_zone IS NULL OR p_ticket_price IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Seat zone and ticket price are required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM customer WHERE customer_id = p_customer_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Customer not found';
  END IF;

  SELECT venue_id INTO v_venue_id FROM event WHERE event_id = p_event_id;
  IF v_venue_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event not found';
  END IF;

  SET v_is_standing = (p_seat_zone = 'STANDING');

  -- Membership discount of this customer (stays 0 when the customer has no rank row)
  SELECT discount_percent INTO v_discount FROM vw_customer_membership WHERE customer_id = p_customer_id;
  SET v_price = ROUND(p_ticket_price * (100 - COALESCE(v_discount, 0)) / 100, 0);

  START TRANSACTION;

  -- Create the pending order; trg_orders_bi generates order_id
  INSERT INTO orders (order_id, customer_id) VALUES (NULL, p_customer_id);

  -- Read back the generated id: the newest order of this customer
  SELECT order_id INTO p_order_id
    FROM orders
   WHERE customer_id = p_customer_id
   ORDER BY CAST(SUBSTRING(order_id, 3) AS UNSIGNED) DESC
   LIMIT 1;

  -- Add the tickets one by one; trg_ticket_bi enforces every business rule
  WHILE v_i < p_quantity DO
    SET v_seat_id = NULL;

    IF v_is_standing = 0 THEN
      -- First free seat of this zone in the event's venue
      SELECT s.seat_id INTO v_seat_id
        FROM seat s
       WHERE s.venue_id  = v_venue_id
         AND s.seat_zone = p_seat_zone
         AND NOT EXISTS (SELECT 1 FROM ticket t
                          WHERE t.seat_id = s.seat_id
                            AND t.event_id = p_event_id)
       ORDER BY s.seat_row, s.seat_number
       LIMIT 1;

      IF v_seat_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Not enough available seats in this zone';
      END IF;
    END IF;

    -- customer_id is the `buy` link: the ticket belongs to the customer who placed the order
    INSERT INTO ticket (seat_id, event_id, order_id, customer_id, ticket_price, is_standing)
    VALUES (v_seat_id, p_event_id, p_order_id, p_customer_id, v_price, v_is_standing);

    SET v_i = v_i + 1;
  END WHILE;

  COMMIT;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/procedure/pc_cancel_order.sql
-- ==========================================================
USE myv_myTickets;

DROP PROCEDURE IF EXISTS pc_cancel_order;

DELIMITER $$

-- Cancel an order that has NOT been paid yet.
-- A paid order can never be cancelled (also enforced by the triggers).
-- Cancelling sets the status to 'failed'; trg_orders_au then deletes the tickets
-- and the virtual STANDING seats, so the seats become available again.
-- The order row is kept as history.
CREATE PROCEDURE pc_cancel_order(
  IN p_order_id VARCHAR(20)
)
BEGIN
  DECLARE v_status VARCHAR(10);

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT status INTO v_status FROM orders WHERE order_id = p_order_id FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order not found';
  END IF;
  IF v_status = 'paid' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A paid order cannot be cancelled';
  END IF;
  IF v_status = 'failed' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order is already cancelled or failed';
  END IF;

  UPDATE orders SET status = 'failed' WHERE order_id = p_order_id;

  COMMIT;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/procedure/pc_expire_orders.sql
-- ==========================================================
USE myv_myTickets;

DROP PROCEDURE IF EXISTS pc_expire_orders;

DELIMITER $$

-- Fail every pending order that has been waiting longer than fn_order_hold_minutes().
-- trg_orders_au then deletes the tickets (and orphaned STANDING seats), so the seats become free again.
-- Paid and already failed orders are never touched.
--   p_expired (OUT)  how many orders were expired
-- Called every minute by the event ev_expire_orders, and at the start of pc_book_tickets
-- (so seats are released even if the scheduler is switched off).
-- No account except the owner is granted EXECUTE on it, so the web app cannot call it.
CREATE PROCEDURE pc_expire_orders(
  OUT p_expired INT
)
BEGIN
  UPDATE orders
     SET status = 'failed'
   WHERE status = 'pending'
     AND place_at < NOW() - INTERVAL fn_order_hold_minutes() MINUTE;

  SET p_expired = ROW_COUNT();
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/procedure/pc_pay_order.sql
-- ==========================================================
USE myv_myTickets;

DROP PROCEDURE IF EXISTS pc_pay_order;

DELIMITER $$

-- Finish payment of a pending order.
-- p_payment_success = 1: the payment method and date are stored on every ticket of the order (the `buy`
--                        attributes), then the order becomes 'paid' and is locked for good (no cancel, no change).
-- An order that has been pending longer than fn_order_hold_minutes() can no longer be paid
--                        (pc_expire_orders fails it within a minute).
-- p_payment_success = 0: the order becomes 'failed'; trg_orders_au then releases its seats.
--                        p_pay_method is ignored in that case and may be NULL.
CREATE PROCEDURE pc_pay_order(
  IN p_order_id        VARCHAR(20),
  IN p_payment_success TINYINT(1),
  IN p_pay_method      VARCHAR(30)
)
BEGIN
  DECLARE v_status     VARCHAR(10);
  DECLARE v_place_at   DATETIME;
  DECLARE v_ticket_cnt INT;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  -- Lock the order row so two payments cannot run at the same time
  SELECT status, place_at INTO v_status, v_place_at FROM orders WHERE order_id = p_order_id FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order not found';
  END IF;
  IF v_status <> 'pending' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only pending orders can be paid';
  END IF;

  IF p_payment_success = 1 AND NOW() >= v_place_at + INTERVAL fn_order_hold_minutes() MINUTE THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This order has expired, please book again';
  END IF;

  SELECT COUNT(*) INTO v_ticket_cnt FROM ticket WHERE order_id = p_order_id;
  IF v_ticket_cnt = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order has no tickets';
  END IF;

  IF p_payment_success = 1 THEN
    IF p_pay_method IS NULL OR p_pay_method = '' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Payment method is required';
    END IF;

    -- A ticket cannot be paid after its event has started
    IF EXISTS (SELECT 1
                 FROM ticket t
                 JOIN event e ON e.event_id = t.event_id
                WHERE t.order_id = p_order_id
                  AND NOW() >= e.start_time) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event has already started';
    END IF;

    -- Store the payment details first: tickets are locked as soon as the order is 'paid'
    UPDATE ticket
       SET pay_method = p_pay_method,
           pay_date   = NOW()
     WHERE order_id = p_order_id;

    UPDATE orders SET status = 'paid' WHERE order_id = p_order_id;
  ELSE
    UPDATE orders SET status = 'failed' WHERE order_id = p_order_id;
  END IF;

  COMMIT;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/procedure/pc_update_customer.sql
-- ==========================================================
USE myv_myTickets;

DROP PROCEDURE IF EXISTS pc_update_customer;

DELIMITER $$

-- Change the profile of a customer: name, email, phone number and (optionally) the password.
-- The customer_app account has no UPDATE right on the customer table, so this procedure is
-- the only way the web app can change a profile.
--   p_password  the NEW password hash, or NULL to keep the current password.
--               The web app checks the current password before it calls this procedure.
--   p_phone_num NULL or '' removes the phone number.
-- customer_id and username never change. A duplicate email is rejected by uq_customer_email.
CREATE PROCEDURE pc_update_customer(
  IN p_customer_id VARCHAR(20),
  IN p_name        VARCHAR(100),
  IN p_email       VARCHAR(100),
  IN p_phone_num   VARCHAR(20),
  IN p_password    VARCHAR(255)
)
BEGIN
  IF NOT EXISTS (SELECT 1 FROM customer WHERE customer_id = p_customer_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Customer not found';
  END IF;
  IF p_name IS NULL OR TRIM(p_name) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Full name is required';
  END IF;
  IF p_email IS NULL OR p_email NOT LIKE '_%@_%' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A valid email address is required';
  END IF;
  IF p_password IS NOT NULL AND p_password = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The password cannot be empty';
  END IF;

  UPDATE customer
     SET name      = TRIM(p_name),
         email     = TRIM(p_email),
         phone_num = NULLIF(TRIM(COALESCE(p_phone_num, '')), ''),
         password  = COALESCE(p_password, password)
   WHERE customer_id = p_customer_id;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/ev_expire_orders.sql
-- ==========================================================
USE myv_myTickets;

DROP EVENT IF EXISTS ev_expire_orders;

DELIMITER $$

-- Scheduled job: every minute, fail the pending orders that were not paid in time.
-- Needs the MySQL event scheduler to be ON:  SHOW VARIABLES LIKE 'event_scheduler';
CREATE EVENT ev_expire_orders
ON SCHEDULE EVERY 1 MINUTE
DO
BEGIN
  CALL pc_expire_orders(@expired_orders);
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets_admin/trigger/trg_admin_bi.sql
-- ==========================================================
USE myv_myTickets_admin;

USE myv_myTickets_admin;

DROP TRIGGER IF EXISTS trg_admin_bi;

DELIMITER $$

-- 1) One person cannot be both an admin and a customer. Customers live in the main database
--    (myv_myTickets), so we look into its customer table with the database.table syntax.
-- 2) Generate admin_id = 'AD' + running number (AD0001, AD0002, ...) when none is given.
CREATE TRIGGER trg_admin_bi
BEFORE INSERT ON admin
FOR EACH ROW
BEGIN
  DECLARE v_next INT;

  IF EXISTS (SELECT 1 FROM myv_myTickets.customer WHERE username = NEW.username) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This username is already a customer and cannot also be an admin';
  END IF;

  IF NEW.admin_id IS NULL OR NEW.admin_id = '' THEN
    SELECT COALESCE(MAX(CAST(SUBSTRING(admin_id, 3) AS UNSIGNED)), 0) + 1
      INTO v_next
      FROM admin
     WHERE admin_id REGEXP '^AD[0-9]+$';

    SET NEW.admin_id = CONCAT('AD', LPAD(v_next, GREATEST(4, CHAR_LENGTH(v_next)), '0'));
  END IF;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets_admin/procedure/pc_add_event.sql
-- ==========================================================
USE myv_myTickets_admin;

USE myv_myTickets_admin;

DROP PROCEDURE IF EXISTS pc_add_event;

DELIMITER $$

-- Create a new event in the MAIN database and write it to audit_log. Only a super_admin may do this.
--   p_admin_id          the admin who performs the action (must exist and be a super_admin)
--   p_standing_capacity 0 (or NULL) means the event has no standing area
--   p_event_id (OUT)    the generated event_id, for example EV07
-- The event ids and the rules (sale_time < start_time, capacity >= 0) come from the triggers
-- trg_event_bi_id and trg_event_bi_chk in the main database.
-- Event and audit_log row are saved together or not at all (transaction).
CREATE PROCEDURE pc_add_event(
  IN  p_admin_id          VARCHAR(20),
  IN  p_venue_id          VARCHAR(20),
  IN  p_event_name        VARCHAR(150),
  IN  p_artist            VARCHAR(150),
  IN  p_sale_time         DATETIME,
  IN  p_start_time        DATETIME,
  IN  p_standing_capacity INT,
  OUT p_event_id          VARCHAR(20)
)
BEGIN
  DECLARE v_level VARCHAR(20);

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET p_event_id = NULL;

  SELECT `level` INTO v_level FROM admin WHERE admin_id = p_admin_id;
  IF v_level IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Admin not found';
  END IF;
  IF v_level <> 'super_admin' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only a super admin can add events';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM myv_myTickets.venue WHERE venue_id = p_venue_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Venue not found';
  END IF;

  START TRANSACTION;

  INSERT INTO myv_myTickets.event
         (event_id, venue_id, event_name, artist, sale_time, start_time, standing_capacity)
  VALUES (NULL, p_venue_id, p_event_name, p_artist, p_sale_time, p_start_time,
          COALESCE(p_standing_capacity, 0));

  -- Read back the generated id: the newest matching event
  SELECT event_id INTO p_event_id
    FROM myv_myTickets.event
   WHERE venue_id   = p_venue_id
     AND event_name = p_event_name
     AND start_time = p_start_time
   ORDER BY CAST(SUBSTRING(event_id, 3) AS UNSIGNED) DESC
   LIMIT 1;

  INSERT INTO audit_log (admin_id, action, target_id)
  VALUES (p_admin_id, 'ADD_EVENT', p_event_id);

  COMMIT;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets_admin/procedure/pc_delete_event.sql
-- ==========================================================
USE myv_myTickets_admin;

USE myv_myTickets_admin;

DROP PROCEDURE IF EXISTS pc_delete_event;

DELIMITER $$

-- Delete an event of the MAIN database and write it to audit_log. Only a super_admin may do this.
--   p_admin_id  the admin who performs the action (must exist and be a super_admin)
--   p_event_id  the event to delete
-- The business rules (no tickets, not started yet) are enforced by the trigger trg_event_bd
-- in the main database, so they also hold for any other DELETE on event.
-- Delete and audit_log row are saved together or not at all (transaction).
CREATE PROCEDURE pc_delete_event(
  IN p_admin_id VARCHAR(20),
  IN p_event_id VARCHAR(20)
)
BEGIN
  DECLARE v_level VARCHAR(20);

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SELECT `level` INTO v_level FROM admin WHERE admin_id = p_admin_id;
  IF v_level IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Admin not found';
  END IF;
  IF v_level <> 'super_admin' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only a super admin can delete events';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM myv_myTickets.event WHERE event_id = p_event_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event not found';
  END IF;

  START TRANSACTION;

  DELETE FROM myv_myTickets.event WHERE event_id = p_event_id;

  INSERT INTO audit_log (admin_id, action, target_id)
  VALUES (p_admin_id, 'DELETE_EVENT', p_event_id);

  COMMIT;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets_admin/procedure/pc_event_stats.sql
-- ==========================================================
USE myv_myTickets_admin;

USE myv_myTickets_admin;

DROP PROCEDURE IF EXISTS pc_event_stats;

DELIMITER $$

-- One-row report for an event in the MAIN database. Any admin (staff or super_admin) may read it.
--   tickets_paid     tickets of paid orders
--   tickets_pending  tickets of pending orders (held, not paid yet)
--   revenue          sum of ticket_price over paid tickets only
--   seats_left       real seats without any ticket (paid or pending)
--   standing_left    standing_capacity minus standing tickets (paid or pending)
-- Read-only: changes nothing.
CREATE PROCEDURE pc_event_stats(
  IN p_admin_id VARCHAR(20),
  IN p_event_id VARCHAR(20)
)
BEGIN
  IF NOT EXISTS (SELECT 1 FROM admin WHERE admin_id = p_admin_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Admin not found';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM myv_myTickets.event WHERE event_id = p_event_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event not found';
  END IF;

  SELECT
    e.event_id,
    e.event_name,
    e.artist,
    (SELECT COUNT(*)
       FROM myv_myTickets.ticket t
       JOIN myv_myTickets.orders o ON o.order_id = t.order_id
      WHERE t.event_id = e.event_id AND o.status = 'paid')    AS tickets_paid,
    (SELECT COUNT(*)
       FROM myv_myTickets.ticket t
       JOIN myv_myTickets.orders o ON o.order_id = t.order_id
      WHERE t.event_id = e.event_id AND o.status = 'pending') AS tickets_pending,
    (SELECT COALESCE(SUM(t.ticket_price), 0)
       FROM myv_myTickets.ticket t
       JOIN myv_myTickets.orders o ON o.order_id = t.order_id
      WHERE t.event_id = e.event_id AND o.status = 'paid')    AS revenue,
    (SELECT COUNT(*)
       FROM myv_myTickets.seat s
      WHERE s.venue_id = e.venue_id AND s.seat_zone <> 'STANDING')
    - (SELECT COUNT(*)
         FROM myv_myTickets.ticket t
         JOIN myv_myTickets.seat s ON s.seat_id = t.seat_id
        WHERE t.event_id = e.event_id AND s.seat_zone <> 'STANDING') AS seats_left,
    e.standing_capacity
    - (SELECT COUNT(*)
         FROM myv_myTickets.ticket t
         JOIN myv_myTickets.seat s ON s.seat_id = t.seat_id
        WHERE t.event_id = e.event_id AND s.seat_zone = 'STANDING')  AS standing_left
  FROM myv_myTickets.event e
  WHERE e.event_id = p_event_id;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets_admin/procedure/pc_update_event.sql
-- ==========================================================
USE myv_myTickets_admin;

USE myv_myTickets_admin;

DROP PROCEDURE IF EXISTS pc_update_event;

DELIMITER $$

-- Edit an event of the MAIN database and write it to audit_log. Only a super_admin may do this.
--   p_admin_id          the admin who performs the action (must exist and be a super_admin)
--   p_event_id          the event to edit
--   p_standing_capacity 0 (or NULL) means the event has no standing area
-- What can change: name, artist, sale time, start time and standing capacity.
-- What cannot change: the venue (the seats of sold tickets belong to it) and the event_id.
-- Rules:
--   * an event that has already started is history and cannot be edited
--   * standing capacity cannot go below the standing tickets that already exist (paid or pending)
--   * sale_time < start_time and capacity >= 0 come from trg_event_bu_chk in the main database
-- Event and audit_log row are saved together or not at all (transaction).
CREATE PROCEDURE pc_update_event(
  IN p_admin_id          VARCHAR(20),
  IN p_event_id          VARCHAR(20),
  IN p_event_name        VARCHAR(150),
  IN p_artist            VARCHAR(150),
  IN p_sale_time         DATETIME,
  IN p_start_time        DATETIME,
  IN p_standing_capacity INT
)
BEGIN
  DECLARE v_level    VARCHAR(20);
  DECLARE v_start    DATETIME;
  DECLARE v_standing INT;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SELECT `level` INTO v_level FROM admin WHERE admin_id = p_admin_id;
  IF v_level IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Admin not found';
  END IF;
  IF v_level <> 'super_admin' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only a super admin can edit events';
  END IF;

  IF p_event_name IS NULL OR TRIM(p_event_name) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event name is required';
  END IF;
  IF p_sale_time IS NULL OR p_start_time IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Sale time and start time are required';
  END IF;

  START TRANSACTION;

  -- Lock the event row while we check it
  SELECT start_time INTO v_start
    FROM myv_myTickets.event WHERE event_id = p_event_id FOR UPDATE;
  IF v_start IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event not found';
  END IF;
  IF v_start <= NOW() THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event has already started and cannot be edited';
  END IF;

  SELECT COUNT(*) INTO v_standing
    FROM myv_myTickets.ticket t
    JOIN myv_myTickets.seat s ON s.seat_id = t.seat_id
   WHERE t.event_id = p_event_id AND s.seat_zone = 'STANDING';
  IF COALESCE(p_standing_capacity, 0) < v_standing THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Standing capacity cannot be lower than the standing tickets already booked';
  END IF;

  UPDATE myv_myTickets.event
     SET event_name        = TRIM(p_event_name),
         artist            = NULLIF(TRIM(COALESCE(p_artist, '')), ''),
         sale_time         = p_sale_time,
         start_time        = p_start_time,
         standing_capacity = COALESCE(p_standing_capacity, 0)
   WHERE event_id = p_event_id;

  INSERT INTO audit_log (admin_id, action, target_id)
  VALUES (p_admin_id, 'UPDATE_EVENT', p_event_id);

  COMMIT;
END$$

DELIMITER ;

